/**
 * Whether a participant fits a study's hard criteria. The company check is
 * the database's (can_apply); this is the rest, so a participant hears why
 * before they press anything.
 */
export function matchCriteria(profile: ProfileFacts, criteria: Criteria, workVerified: boolean): Match {
  const unmet: string[] = []
  if (criteria.require_work && !workVerified) unmet.push('옆자리 회사 인증이 필요해요')
  if (criteria.job_families.length > 0 && !criteria.job_families.includes(profile.job_family)) unmet.push('찾는 직무가 달라요')
  if (criteria.careers.length > 0 && !criteria.careers.includes(profile.career)) unmet.push('찾는 연차가 달라요')
  if (criteria.industries.length > 0 && !criteria.industries.includes(profile.industry)) unmet.push('찾는 업종이 달라요')
  if (criteria.company_sizes.length > 0 && !criteria.company_sizes.includes(profile.company_size)) unmet.push('찾는 회사 규모가 달라요')
  if (criteria.regions.length > 0 && !profile.regions.some((r) => criteria.regions.includes(r))) unmet.push('대면 지역이 달라요')
  if (criteria.tools_any.length > 0) {
    const mine = new Set(profile.tools.map((t) => t.toLowerCase()))
    if (!criteria.tools_any.some((t) => mine.has(t.toLowerCase()))) unmet.push('찾는 도구 사용 경험이 없어요')
  }
  return { ok: unmet.length === 0, unmet }
}

/** Whether a study's way of running suits how the participant said they take part. */
export function suitsModes(profile: ProfileFacts, mode: string, location: string): boolean {
  if (profile.modes.length === 0) return true
  if (mode === 'async') return profile.modes.includes('async')
  return profile.modes.includes(location === 'in_person' ? 'in_person' : 'video')
}

// ---------------------------------------------------------------- answers --

/**
 * Checks a participant's screener answers against the questions, keeping only
 * known answers, and judges them against the rules.
 */
export function judgeScreener(
  questions: ScreenerQuestion[],
  rules: ScreenerRules,
  raw: unknown,
): { answers: Record<string, string | string[]>; eligible: boolean } {
  const source = (typeof raw === 'object' && raw !== null && !Array.isArray(raw) ? raw : {}) as Record<string, unknown>
  const errors: FieldErrors = {}
  const answers: Record<string, string | string[]> = {}
  let eligible = true
  for (const q of questions) {
    const path = `answers.${q.id}`
    const value = Object.hasOwn(source, q.id) ? source[q.id] : undefined
    if (q.kind === 'text') {
      const answer = text(value, 1000)
      if (!answer && q.required) errors[path] = '답을 입력해 주세요.'
      if (answer) answers[q.id] = answer
      continue
    }
    const ids = q.kind === 'multi'
      ? [...new Set(list(value).filter((v): v is string => typeof v === 'string'))]
      : typeof value === 'string' && value ? [value] : []
    if (ids.some((id) => !q.options.some((o) => o.id === id))) {
      errors[path] = '선택지에 없는 답이 있어요.'
      continue
    }
    if (ids.length === 0) {
      if (q.required) errors[path] = '하나 이상 골라 주세요.'
      continue
    }
    answers[q.id] = q.kind === 'multi' ? ids : ids[0]!
    if (ids.some((id) => (rules[q.id] ?? []).includes(id))) eligible = false
  }
  if (Object.keys(errors).length > 0) throw invalid(errors, '답하지 않은 질문이 있어요.')
  return { answers, eligible }
}

export function judgeSubmission(form: FormQuestion[], raw: unknown): Record<string, string | string[] | number> {
  const source = (typeof raw === 'object' && raw !== null && !Array.isArray(raw) ? raw : {}) as Record<string, unknown>
  const errors: FieldErrors = {}
  const out: Record<string, string | string[] | number> = {}
  for (const q of form) {
    const path = `submission.${q.id}`
    const value = Object.hasOwn(source, q.id) ? source[q.id] : undefined
    switch (q.kind) {
      case 'text':
      case 'long':
      case 'url': {
        const answer = text(value, q.kind === 'long' ? 4000 : 500)
        if (!answer) {
          if (q.required) errors[path] = '답을 입력해 주세요.'
          break
        }
        if (q.kind === 'url' && !isWebLink(answer)) {
          errors[path] = 'http(s)로 시작하는 주소를 넣어 주세요.'
          break
        }
        out[q.id] = answer
        break
      }
      case 'rating': {
        const n = typeof value === 'number' ? value : Number(value)
        if (!Number.isInteger(n) || n < 1 || n > 5) {
          if (q.required || (value !== undefined && value !== null && value !== '')) errors[path] = '1~5 중에서 골라 주세요.'
          break
        }
        out[q.id] = n
        break
      }
      case 'choice':
      case 'multi': {
        const ids = q.kind === 'multi'
          ? [...new Set(list(value).filter((v): v is string => typeof v === 'string'))]
          : typeof value === 'string' && value ? [value] : []
        if (ids.some((id) => !q.options.some((o) => o.id === id))) {
          errors[path] = '선택지에 없는 답이 있어요.'
          break
        }
        if (ids.length === 0) {
          if (q.required) errors[path] = '하나 이상 골라 주세요.'
          break
        }
        out[q.id] = q.kind === 'multi' ? ids : ids[0]!
        break
      }
    }
  }
  if (Object.keys(errors).length > 0) throw invalid(errors, '답하지 않은 질문이 있어요.')
  return out
}

