describe('screener', () => {
  const written = [
    {
      text: '업무에서 생성형 AI를 쓰나요?',
      kind: 'single',
      options: [{ label: '매일', disqualify: false }, { label: '가끔' }, { label: '안 써요', disqualify: true }],
    },
    { text: '주로 쓰는 도구', kind: 'multi', options: [{ label: 'ChatGPT' }, { label: 'Claude' }, { label: '기타' }] },
    { text: '어떤 일에 쓰는지 한 줄로', kind: 'text', required: false },
  ]

  it('splits what participants see from the rules that rule people out', () => {
    const { questions, rules } = parseScreener(written)
    expect(questions.map((q) => q.id)).toEqual(['q1', 'q2', 'q3'])
    expect(JSON.stringify(questions)).not.toContain('disqualify')
    expect(rules).toEqual({ q1: ['o3'] })
    // And back together for editing.
    const editing = screenerForEditing(questions, rules) as { options: { disqualify: boolean }[] }[]
    expect(editing[0]!.options.map((o) => o.disqualify)).toEqual([false, false, true])
  })

  it('refuses a screener nobody could pass, and a choice with one option', () => {
    expect(() => parseScreener([{ text: 'q', options: [{ label: 'a', disqualify: true }, { label: 'b', disqualify: true }] }])).toThrowError()
    expect(() => parseScreener([{ text: 'q', options: [{ label: 'only' }] }])).toThrowError()
    expect(() => parseScreener(new Array(11).fill({ text: 'q', kind: 'text' }))).toThrowError()
  })

  it('judges answers, keeping only known ones', () => {
    const { questions, rules } = parseScreener(written)
    const pass = judgeScreener(questions, rules, { q1: 'o1', q2: ['o1', 'o2', 'o2'], q3: '  문서 요약  ', extra: 'x' })
    expect(pass).toEqual({ eligible: true, answers: { q1: 'o1', q2: ['o1', 'o2'], q3: '문서 요약' } })
    expect(judgeScreener(questions, rules, { q1: 'o3', q2: ['o1'] }).eligible).toBe(false)
    expect(() => judgeScreener(questions, rules, { q1: 'o9', q2: ['o1'] })).toThrowError()
    expect(() => judgeScreener(questions, rules, { q2: ['o1'] })).toThrowError()
    // A prototype key is not an answer.
    expect(() => judgeScreener(questions, rules, JSON.parse('{"__proto__": {"q1": "o1"}, "q2": ["o1"]}'))).toThrowError()
  })
})

