/** A browser-like client: keeps cookies and echoes the CSRF token. */
export class Client {
  constructor(label, admin = false) {
    this.label = label
    this.admin = admin
    this.cookies = new Map()
  }
  get csrf() {
    return this.admin ? (this.cookies.get('yi_acsrf') ?? '') : (this.cookies.get('yi_csrf') ?? '')
  }
  cookieHeader() {
    return [...this.cookies.entries()].map(([k, val]) => `${k}=${val}`).join('; ')
  }
  async request(method, path, body, extra = {}) {
    const headers = { origin: BASE, ...extra }
    if (body !== undefined) headers['content-type'] = 'application/json'
    if (this.cookies.size > 0) headers.cookie = this.cookieHeader()
    if (this.csrf && !extra.noCsrf) headers['x-insight-csrf'] = this.csrf
    delete headers.noCsrf
    if (this.admin) headers['x-insight-session'] = 'admin'
    const response = await fetch(`${BASE}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
      redirect: 'manual',
    })
    for (const raw of response.headers.getSetCookie?.() ?? []) {
      const [pair] = raw.split(';')
      const eq = pair.indexOf('=')
      if (eq > 0) {
        const name = pair.slice(0, eq).trim()
        const value = decodeURIComponent(pair.slice(eq + 1).trim())
        if (value === '') this.cookies.delete(name)
        else this.cookies.set(name, value)
      }
    }
    const type = response.headers.get('content-type') ?? ''
    if (!type.includes('json')) {
      // Decoded by hand: response.text() drops a leading BOM, which is what a CSV check needs to see.
      const bytes = new Uint8Array(await response.arrayBuffer())
      const text = new TextDecoder('utf-8', { ignoreBOM: true }).decode(bytes)
      return { status: response.status, body: null, text, bytes, headers: response.headers }
    }
    const text = await response.text()
    let json = null
    try {
      json = text ? JSON.parse(text) : null
    } catch {
      json = { raw: text.slice(0, 200) }
    }
    return { status: response.status, body: json, text, headers: response.headers }
  }
  get(path) {
    return this.request('GET', path)
  }
  post(path, body, extra) {
    return this.request('POST', path, body ?? {}, extra)
  }
  put(path, body) {
    return this.request('PUT', path, body ?? {})
  }
  patch(path, body) {
    return this.request('PATCH', path, body ?? {})
  }
  del(path) {
    return this.request('DELETE', path)
  }
}

