      - name: Build
        run: npm run build
      - name: Development settings
        run: node scripts/ci-env.mjs
      - name: Migrate
        run: DATABASE_URL=postgres://postgres:devpass@127.0.0.1:55442/insight INSIGHT_APP_DB_PASSWORD=devapppass INSIGHT_GATEWAY_DB_PASSWORD=devgatewaypass node scripts/migrate.mjs
      - name: Start the server
        run: |
          set -a; . ./.env.dev; set +a
          nohup node apps/server/dist/index.js > server.log 2>&1 &
          for i in $(seq 1 60); do curl -sf http://localhost:8789/api/v1/health > /dev/null && exit 0; sleep 1; done
