#!/usr/bin/env node
// Apply db/migrations/*.sql in order, once each, inside a transaction.
//
// The ledger is public.insight_schema_migrations, not schema_migrations: this
// service can share a Postgres instance with yeopjari (its schemas are `insight`
// and `insight_priv`), and the two must never read each other's ledger.
//
//   DATABASE_URL=postgres://... node scripts/migrate.mjs
//   DATABASE_URL=... INSIGHT_APP_DB_PASSWORD=... node scripts/migrate.mjs
//
// The optional app password gives the restricted insight_app role a login, so
// the BFF can connect as the role the RLS policies are written against.
import { readFile, readdir } from 'node:fs/promises'
import { createHash } from 'node:crypto'
import path from 'node:path'
import postgres from 'postgres'
import { pgConnection } from './pg-connect.mjs'

const url = process.env.DATABASE_URL || process.env.INSIGHT_ADMIN_DB_URL
if (!url) {
  console.error('migrate: set DATABASE_URL to a superuser/owner connection string')
  process.exit(2)
}

const dir = path.resolve(import.meta.dirname, '..', 'db', 'migrations')
const files = (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort()
if (files.length === 0) {
  console.error('migrate: no migrations found in', dir)
  process.exit(2)
}

const sql = postgres(
  ...pgConnection(url, {
    max: 1,
    prepare: false,
    connect_timeout: 30,
    idle_timeout: 20,
    onnotice: () => {},
  }),
)

try {
  await sql.unsafe(`
    CREATE TABLE IF NOT EXISTS public.insight_schema_migrations (
      id         text PRIMARY KEY,
      checksum   text NOT NULL,
      applied_at timestamptz NOT NULL DEFAULT now()
    )
  `)

  const applied = new Map(
    (await sql`SELECT id, checksum FROM public.insight_schema_migrations`).map((r) => [r.id, r.checksum]),
  )

  let ran = 0
  for (const file of files) {
    const id = file.replace(/\.sql$/, '')
    const body = await readFile(path.join(dir, file), 'utf8')
    const checksum = createHash('sha256').update(body).digest('hex').slice(0, 16)

    const seen = applied.get(id)
    if (seen) {
      if (seen !== checksum) {
        console.error(
          `migrate: ${id} already applied with a different checksum.\n` +
            '  Migrations are immutable once applied - add a new file instead of editing this one.',
        )
        process.exit(1)
      }
      continue
    }

    process.stdout.write(`migrate: applying ${id} ... `)
    const started = Date.now()
    await sql.begin(async (tx) => {
      await tx.unsafe(body).simple()
      await tx`INSERT INTO public.insight_schema_migrations (id, checksum) VALUES (${id}, ${checksum})`
    })
    console.log(`done (${Date.now() - started}ms)`)
    ran++
  }

  // On the shared Supabase database no one logs in as a service role and the
  // gateway is managed in one place (yeopjari engineering/shared-db.md): a
  // password here would turn insight_app's LOGIN back on - connections outside
  // the gateway's cap - or change the gateway's password under every service.
  // Deploy scripts load every key in cloud.env, so this does not rely on them.
  const sharedDatabase = /\.supabase\.com?[:/]/.test(url)
  if (sharedDatabase && (process.env.INSIGHT_APP_DB_PASSWORD || process.env.INSIGHT_GATEWAY_DB_PASSWORD)) {
    console.log('migrate: shared database - login roles left as they are (INSIGHT_APP_DB_PASSWORD / INSIGHT_GATEWAY_DB_PASSWORD ignored)')
  }
  const appPassword = sharedDatabase ? undefined : process.env.INSIGHT_APP_DB_PASSWORD
  if (appPassword) {
    await sql.unsafe(`ALTER ROLE insight_app LOGIN PASSWORD ${literal(appPassword)}`)
    console.log('migrate: insight_app login password set')
  }

  // Re-assert grants for anything the migrations created after the grant ran.
  await sql.unsafe(`
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA insight, insight_priv TO insight_app;
    GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA insight, insight_priv TO insight_app;
  `).simple()

  // The services on the shared database pool their connections through one
  // gateway login (irumx_gateway). Wherever it exists it may switch into
  // insight_app - and only switch: INHERIT FALSE leaves the gateway itself without
  // any privilege, so a statement that forgot to switch is refused.
  // Production's gateway is made once for all services (yeopjari
  // scripts/shared-db-gateway.mjs); a development database makes its own
  // (INSIGHT_GATEWAY_DB_PASSWORD).
  const gatewayPassword = sharedDatabase ? undefined : process.env.INSIGHT_GATEWAY_DB_PASSWORD
  if (gatewayPassword) {
    await sql.unsafe(`DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'irumx_gateway') THEN CREATE ROLE irumx_gateway; END IF; END $$`).simple()
    await sql.unsafe(`ALTER ROLE irumx_gateway LOGIN NOINHERIT PASSWORD ${literal(gatewayPassword)}`)
  }
  const gateway = await sql`SELECT 1 FROM pg_roles WHERE rolname = 'irumx_gateway'`
  if (gateway.length > 0) {
    await sql.unsafe('GRANT insight_app TO irumx_gateway WITH INHERIT FALSE, SET TRUE')
    console.log('migrate: irumx_gateway may switch to insight_app')
  }

  console.log(
    ran === 0
      ? `migrate: already up to date (${files.length} migration${files.length === 1 ? '' : 's'})`
      : `migrate: applied ${ran} migration${ran === 1 ? '' : 's'}`,
  )
} finally {
  await sql.end({ timeout: 5 })
}

function literal(s) {
  return `'${String(s).replace(/'/g, "''")}'`
}
