export function parseForm(raw: unknown): FormQuestion[] {
  const errors: FieldErrors = {}
  const out: FormQuestion[] = []
  const entries = list(raw)
  if (entries.length > 20) errors.submission_form = '제출 질문은 20개까지예요.'
  entries.slice(0, 20).forEach((entry, index) => {
    const q = (typeof entry === 'object' && entry !== null ? entry : {}) as Record<string, unknown>
    const path = `submission_form[${index}]`
    const questionText = text(q.text, 300)
    if (!questionText) {
      errors[path] = '질문 내용을 입력해 주세요.'
      return
    }
    const kinds: FormKind[] = ['text', 'long', 'choice', 'multi', 'rating', 'url']
    const kind = kinds.includes(q.kind as FormKind) ? (q.kind as FormKind) : 'long'
    let id = typeof q.id === 'string' && ID.test(q.id) ? q.id : `f${index + 1}`
    if (out.some((x) => x.id === id)) id = `f${index + 1}x`
    const options = kind === 'choice' || kind === 'multi'
      ? parseOptions(q.options, path, errors).map(({ id: oid, label }) => ({ id: oid, label }))
      : []
    if ((kind === 'choice' || kind === 'multi') && options.length < 2) errors[path] = '선택지를 2개 이상 넣어 주세요.'
    out.push({ id, text: questionText, kind, options, required: q.required !== false })
  })
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return out
}

export function readForm(raw: unknown): FormQuestion[] {
  return list(raw).filter((q): q is FormQuestion =>
    typeof q === 'object' && q !== null && typeof (q as FormQuestion).id === 'string')
}

export function isWebLink(raw: string): boolean {
  try {
    const url = new URL(raw)
    return (url.protocol === 'https:' || url.protocol === 'http:') && raw.length <= 500
  } catch {
    return false
  }
}

export function parseLinks(raw: unknown): TaskLink[] {
  const errors: FieldErrors = {}
  const out: TaskLink[] = []
  list(raw).slice(0, 8).forEach((entry, index) => {
    const l = (typeof entry === 'object' && entry !== null ? entry : {}) as Record<string, unknown>
    const url = text(l.url, Infinity)
    if (!url) return
    if (url.length > 500) {
      errors[`task_links[${index}]`] = '주소는 500자까지 넣을 수 있어요.'
