/**
 * Production's database conditions, for measuring (scripts/latency-lab.mjs):
 *   INSIGHT_DB_PREPARE=off     no kept prepared statements - behind Hyperdrive
 *                           every request starts on a new connection, so a
 *                           statement cache never helps there
 *   INSIGHT_SERVER_TIMING=on   the Server-Timing header the Pages adapter sends:
 *                           statements and the time each was sent
 * and for checking the driver patch (packages/core/vendor/postgres/PATCHED.md):
 *   INSIGHT_DB_DESCRIBE=audit  describe every statement, log each parameter the
 *                           skip-describe path would have sent differently
 */
const flag = (name: string): string => (process.env[name] ?? '').trim().toLowerCase()
const serverTiming = ['1', 'on', 'true'].includes(flag('INSIGHT_SERVER_TIMING'))
interface Meter {
  statements: number
  sentAt: number[]
  started: number
}
const meters = new AsyncLocalStorage<Meter>()

let app: ReturnType<typeof createApp>
try {
  const describe = flag('INSIGHT_DB_DESCRIBE')
  const database =
    flag('INSIGHT_DB_PREPARE') === 'off' || serverTiming || describe
      ? new Database(process.env.INSIGHT_DATABASE_URL ?? '', {
          max: 10,
          role: process.env.INSIGHT_DB_ROLE || undefined,
          // Measuring: keep connections open between samples. Production
          // reaches Hyperdrive, whose pool to the database is already open.
          idleTimeout: serverTiming ? 600 : undefined,
          prepare: flag('INSIGHT_DB_PREPARE') !== 'off',
          describe: describe === 'audit' || describe === 'always' ? describe : 'when-needed',
          onDescribeMismatch: (detail) =>
            console.error(JSON.stringify({ level: 'error', message: 'describe mismatch', ...detail })),
          onStatement: serverTiming
            ? () => {
                const meter = meters.getStore()
                if (!meter) return
                meter.statements += 1
                meter.sentAt.push(Date.now() - meter.started)
              }
            : undefined,
        })
      : undefined
  app = createApp(process.env as Record<string, string | undefined>, { maxConnections: 10, database })
} catch (err) {
  if (err instanceof EnvError) {
    console.error(`설정 오류: ${err.message}`)
    process.exit(2)
  }
  throw err
}

const staticFiles = new StaticFiles({ root: webRoot })

