/** Runs one statement as insight_app acting for `accountId` (the RLS bypass attempts). */
export async function asMember(accountId, roles, fn) {
  return appDb.begin(async (tx) => {
    await tx`SELECT set_config('insight.account_id', ${accountId ?? ''}, true), set_config('insight.roles', ${roles}, true),
                    set_config('insight.internal', '', true)`
    return fn(tx)
  }).then((value) => ({ ok: true, value }), (err) => ({ ok: false, code: err.code, message: err.message }))
}

